using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Windows.Forms;
// Relocate before removing our own file. Use the installed, updated inventory;
// this avoids embedding an obsolete full installer in the program uninstaller.
internal static class NativeUninstall {
    static bool Installed(string root){try{if(!File.Exists(Path.Combine(root,"CodexLiveBackground.exe"))||!File.Exists(Path.Combine(root,"manifest.json")))return false;var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,".codex-background-install.json")));return Convert.ToString(data["productId"])=="codex-live-background/exe"&&RootPath(Convert.ToString(data["root"])).TrimEnd('\\').Equals(RootPath(root).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase);}catch{return false;}}
    internal static string ResolveRoot(string proposed){
        var candidates=new System.Collections.Generic.List<string>{proposed,Convert.ToString(Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\CodexLiveBackground","InstallRoot",null))};
        try{string file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"CodexHub\installations.json");var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(file));if(Convert.ToString(data["productId"])=="codex-live-background/exe")foreach(var item in ((System.Collections.IEnumerable)data["installations"]).Cast<object>().Reverse()){var entry=(System.Collections.Generic.Dictionary<string,object>)item;if(Convert.ToString(entry["status"])=="installed")candidates.Add(Convert.ToString(entry["root"]));}}catch{}
        foreach(string root in candidates)if(!String.IsNullOrWhiteSpace(root)&&Installed(root))return RootPath(root);return RootPath(proposed);
    }
    static string Quote(string value){var text=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='"')text.Append('\\',slashes*2+1).Append(c);else text.Append('\\',slashes).Append(c);slashes=0;}return text.Append('\\',slashes*2).Append('"').ToString();}
    internal static string RootPath(string value){string root=Path.GetFullPath(value);return root.Equals(Path.GetPathRoot(root),StringComparison.OrdinalIgnoreCase)?root:root.TrimEnd('\\');}
    static bool NeedsElevation(string root){if(new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator))return false;try{using(var file=new FileStream(Path.Combine(root,".codexhub-uninstall-"+Guid.NewGuid().ToString("N")),FileMode.CreateNew,FileAccess.Write,FileShare.None,4096,FileOptions.DeleteOnClose)){}return false;}catch(UnauthorizedAccessException){return true;}}
    static void CopyTree(string source,string destination){if(!Directory.Exists(source))return;if((File.GetAttributes(source)&FileAttributes.ReparsePoint)!=0)throw new IOException("卸载目录包含链接。");Directory.CreateDirectory(destination);foreach(string file in Directory.GetFiles(source)){if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("卸载文件包含链接。");File.Copy(file,Path.Combine(destination,Path.GetFileName(file)));}foreach(string folder in Directory.GetDirectories(source))CopyTree(folder,Path.Combine(destination,Path.GetFileName(folder)));}
    internal static string Prepare(string root,string temporary){string stage=Path.Combine(temporary,"package");Directory.CreateDirectory(stage);foreach(string name in new[]{"native-actions.ps1","native-lifecycle.ps1","service-removal.ps1","service-compatibility.ps1","service-compatibility.json","shortcuts.ps1","uninstall-data.ps1","upgrade.ps1","legacy-msi-products.json","legacy-managers.json","historical-install-files.json","cloud-pets.json","manifest.json"})File.Copy(Path.Combine(root,name),Path.Combine(stage,name));CopyTree(Path.Combine(root,@"engine\scripts"),Path.Combine(stage,@"engine\scripts"));CopyTree(Path.Combine(root,@"engine\assets"),Path.Combine(stage,@"engine\assets"));CopyTree(Path.Combine(root,@"engine\runtime\node"),Path.Combine(stage,@"engine\runtime\node"));return stage;}
    [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=ResolveRoot(args.Length>=2&&args[0]=="--uninstall"?args[1]:AppDomain.CurrentDomain.BaseDirectory);bool relocated=args.Length>=3&&args[2]=="--relocated";
        try{
            if(!File.Exists(Path.Combine(root,"CodexLiveBackground.exe"))||!File.Exists(Path.Combine(root,"manifest.json")))throw new IOException("请选择有效的 CodexHub 安装目录。");
            if(relocated&&args.Length>=5&&args[3]=="--owner"&&args[4]!=System.Security.Principal.WindowsIdentity.GetCurrent().User.Value)throw new IOException("Windows 授权切换到了其他账号，请使用原账号确认。");
            if(!relocated){if(MessageBox.Show("卸载 CodexHub 及其后台服务？\r\n原始壁纸文件和 Codex 登录资料保留。","CodexHub",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return 0;string temp=Path.Combine(Path.GetTempPath(),"CodexHubUninstall-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string helper=Path.Combine(temp,"Uninstall.exe");File.Copy(Application.ExecutablePath,helper);using(var p=Process.Start(new ProcessStartInfo(helper,"--uninstall "+Quote(root)+" --relocated --owner "+Quote(System.Security.Principal.WindowsIdentity.GetCurrent().User.Value)){UseShellExecute=NeedsElevation(root),Verb="runas"})){}return 0;}
            var form=new Form{Text="CodexHub · 卸载",ClientSize=new Size(540,190),FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterScreen,ControlBox=false};var label=new Label{Bounds=new Rectangle(22,24,496,105),Text="正在准备卸载组件…"};var bar=new ProgressBar{Bounds=new Rectangle(22,141,496,18),Style=ProgressBarStyle.Marquee};form.Controls.Add(label);form.Controls.Add(bar);
            form.Shown+=delegate{new Thread(delegate(){try{string stage=Prepare(root,AppDomain.CurrentDomain.BaseDirectory);string operation=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"operation");Directory.CreateDirectory(operation);
                string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");var info=new ProcessStartInfo(ps,"-NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File "+Quote(Path.Combine(stage,"native-actions.ps1"))+" -Action Uninstall -InstallRoot "+Quote(root)+" -SetupExecutable "+Quote(Application.ExecutablePath)+" -OperationRoot "+Quote(operation)+" -ManagerPid "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};
                using(var p=new Process{StartInfo=info}){p.OutputDataReceived+=delegate(object sender,DataReceivedEventArgs e){if(e.Data!=null)form.BeginInvoke((MethodInvoker)delegate{label.Text=e.Data;});};p.Start();p.BeginOutputReadLine();var error=p.StandardError.ReadToEndAsync();p.WaitForExit();if(p.ExitCode!=0)throw new IOException(error.Result);}
                form.BeginInvoke((MethodInvoker)delegate{bar.Style=ProgressBarStyle.Blocks;bar.Value=100;label.Text="卸载完成，原始壁纸与 Codex 登录资料保留。";form.ControlBox=true;});
            }catch(Exception e){form.BeginInvoke((MethodInvoker)delegate{form.ControlBox=true;bar.Style=ProgressBarStyle.Blocks;label.Text="卸载未完成："+e.Message;});}}){IsBackground=true}.Start();};Application.Run(form);return 0;
        }catch(Exception error){MessageBox.Show(error.Message,"CodexHub");return 1;}
    }
}
